css:
/* Habamax (dark) / Xamabah (light) - https://github.com/habamax/vim-habamax */
/* diff markers use Added/Removed; diff line backgrounds resolve to DiffAdd/DiffDelete */
:root.dark{--diff-addition:#5fd75f;--diff-deletion:#d75f5f;--diff-addition-foreground:#5fd75f;--diff-deletion-foreground:#d75f5f}
:root.dark diffs-container{--diff-addition:#417d33;--diff-deletion:#5b2615}
:root:not(.dark){--diff-addition:#008700;--diff-deletion:#d70000;--diff-addition-foreground:#008700;--diff-deletion-foreground:#d70000}
:root:not(.dark) diffs-container{--diff-addition:#97b797;--diff-deletion:#d79797}
/* Visual */
:root.dark ::selection{background:#1a3456}
:root:not(.dark) ::selection{background:#a0c0e0}
/* chat code blocks: syntax groups */
.chat-markdown-shiki pre{color:var(--app-theme-code-foreground)!important}
:root.dark .chat-markdown-shiki span:is([style*="#5ecc71" i],[style*="rgb(94, 204, 113)"]){color:#87af87!important}
:root.dark .chat-markdown-shiki span:is([style*="#ffd452" i],[style*="rgb(255, 212, 82)"],[style*="#68cdf2" i],[style*="rgb(104, 205, 242)"]){color:#d7af87!important}
:root.dark .chat-markdown-shiki span:is([style*="#ff678d" i],[style*="rgb(255, 103, 141)"],[style*="#08c0ef" i],[style*="rgb(8, 192, 239)"]){color:#af87af!important}
